(function(){"use strict";function l(s,r){const t=r/100*(s.length-1),e=Math.floor(t),n=Math.ceil(t);if(e===n)return s[e];const o=t-e;return s[e]*(1-o)+s[n]*o}self.onmessage=s=>{const{rendimenti:r}=s.data,t=r.length;if(t===0){self.postMessage({inferiore:null,superiore:null});return}const e=new Array(1e4);for(let n=0;n<1e4;n+=1){let o=0;for(let c=0;c<t;c+=1)o+=r[Math.floor(Math.random()*t)];e[n]=o/t*100}e.sort((n,o)=>n-o),self.postMessage({inferiore:l(e,2.5),superiore:l(e,97.5)})}})();
